document.addEventListener("DOMContentLoaded",()=>{const e=document.body,t=document.getElementById("theme-toggle");"light"===localStorage.getItem("machili-theme")&&(e.classList.add("light-theme"),t&&(t.textContent="🌙")),t&&t.addEventListener("click",()=>{const s=e.classList.toggle("light-theme");localStorage.setItem("machili-theme",s?"light":"dark"),t.textContent=s?"🌙":"☀️"});const s=document.querySelectorAll(".reveal");if("IntersectionObserver"in window){const e=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("is-visible"),t.unobserve(e.target))})},{threshold:.12});s.forEach(t=>e.observe(t))}else s.forEach(e=>e.classList.add("is-visible"))});